const $ = s => document.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names = ['Ardy Pratama','Nadia Putri','Rizky Aditya','Sarah Wijaya','Dimas Saputra','Michelle Tan','Kevin Hartono','Alya Rahman','Bima Santoso','Clara Lim','Fajar Yusuf','Tania Dewi','Reza Malik','Nina Sari','Andi Putra','Lina Chen','Yoga Prakoso','Maya Lestari','Rafi Hadi','Dina Ayu','Ivan Setiawan','Siska Dewi','Bayu Nugraha','Rina Hartati'];
const key='rally-prototype-v1';
let currentView='overview', round=0, submitHandler, state;
const initials=n=>n.split(' ').map(w=>w[0]).slice(0,2).join('');
const short=n=>n.split(' ')[0]+' '+(n.split(' ')[1]?.[0]||'')+'.';
function generate(meet){
  if(meet.mode==='mixed')return generateMixed(meet);
  const counts=meet.players.map(()=>0), pairs={}, opponents={}, matches=[];
  const pairKey=(a,b)=>[a,b].sort((x,y)=>x-y).join('-');
  let seed=37;const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};
  let fixed=Array.from({length:Math.floor(meet.players.length/2)},(_,i)=>[i*2,i*2+1]);
  for(let r=0;r<meet.rounds;r++){
    let selected=[];
    if(meet.mode==='fixed'){
      if(r===0 && fixed.length%2)fixed.push(null);
      const available=[];for(let i=0;i<fixed.length/2;i++)if(fixed[i]&&fixed[fixed.length-1-i])available.push([fixed[i],fixed[fixed.length-1-i]]);
      available.sort((a,b)=>a.flat().reduce((s,p)=>s+counts[p],0)-b.flat().reduce((s,p)=>s+counts[p],0));
      selected=available.slice(0,meet.courts);fixed=[fixed[0],fixed[fixed.length-1],...fixed.slice(1,-1)];
    }else{
      const active=meet.players.map((_,i)=>({i,n:rand()})).sort((a,b)=>counts[a.i]-counts[b.i]||a.n-b.n).slice(0,Math.min(meet.courts,Math.floor(meet.players.length/4))*4).map(v=>v.i);
      let best=Infinity;
      for(let attempt=0;attempt<250;attempt++){
        const shuffled=[...active];for(let i=shuffled.length-1;i>0;i--){const j=Math.floor(rand()*(i+1));[shuffled[i],shuffled[j]]=[shuffled[j],shuffled[i]]}
        let score=0, candidate=[];
        for(let i=0;i<shuffled.length;i+=4){const a=shuffled.slice(i,i+2),b=shuffled.slice(i+2,i+4);score+=((pairs[pairKey(...a)]||0)+(pairs[pairKey(...b)]||0))*20;for(const x of a)for(const y of b)score+=(opponents[pairKey(x,y)]||0);if(meet.mode==='balanced')score+=Math.abs(a.reduce((s,p)=>s+meet.players[p].skill,0)-b.reduce((s,p)=>s+meet.players[p].skill,0))*30;candidate.push([a,b]);}
        if(score<best){best=score;selected=candidate;}
      }
    }
    selected.forEach((teams,c)=>{teams.flat().forEach(p=>counts[p]++);teams.forEach(t=>pairs[pairKey(...t)]=(pairs[pairKey(...t)]||0)+1);for(const a of teams[0])for(const b of teams[1])opponents[pairKey(a,b)]=(opponents[pairKey(a,b)]||0)+1;matches.push({id:`${meet.id}-${r}-${c}`,round:r,court:c+1,teams,status:'ready',stats:{}})});
  }
  meet.matches=matches;
}
function makeMeet(id,name,n=10,courts=2,rounds=5,mode='rotating',format='4'){
  const m={id,name,venue:'The Padel House, Jakarta',date:'2026-10-31',time:'16:00',duration:120,courts,rounds,mode,format,timing:true,organizers:[],fixedPairs:mode==='mixed'?[[0,1]]:[],players:names.slice(0,n).map((name,i)=>({name,skill:[3,3.5,3,2.5,4,3.5,3,2.5,4,3][i%10],team:Math.floor(i/2)+1})),matches:[]};generate(m);return m;
}
function fresh(){const a=makeMeet('weekend','Saturday Social');const b=makeMeet('sunset','Sunset Doubles',8,1,6,'fixed','5');b.time='17:00';return {selected:a.id,meets:[a,b],club:{name:'Weekend Padel Club',organizers:['user-0','user-1']},users:names.map((name,i)=>({id:'user-'+i,name}))};}
try{state=JSON.parse(localStorage.getItem(key))||fresh()}catch{state=fresh()}
state.club ??= {name:'Weekend Padel Club',organizers:['user-0','user-1']};
state.users ??= names.map((name,i)=>({id:'user-'+i,name}));
state.meets.forEach(m=>{m.organizers ??= [];});
const meet=()=>state.meets.find(m=>m.id===state.selected)||state.meets[0];
function persist(){try{localStorage.setItem(key,JSON.stringify(state))}catch{toast('Browser storage unavailable. Changes last only for this visit.')}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
const formatName=m=>m.format==='5'?'Best of 5 games':`Race to ${m.format} games`;
const modeName=m=>({fixed:'Fixed partners',rotating:'Rotating partners',balanced:'Skill-balanced partners',mixed:'Mixed · fixed & rotating'}[m.mode]);
const target=m=>m.format==='5'?3:Number(m.format);
const teamText=(m,t)=>t.map(p=>esc(short(m.players[p].name))).join(' & ');
function counts(m,completed=false){return m.players.map((_,i)=>m.matches.filter(x=>(!completed||x.status==='done')&&x.teams.flat().includes(i)).length)}
function dateText(m){return new Date(m.date+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'})}
function statsCards(m){const c=counts(m),done=m.matches.filter(x=>x.status==='done').length;return `<div class="stats"><div class="stat"><div class="stat-top">Players checked in <span class="stat-icon">♧</span></div><strong>${m.players.length}</strong><small>ready to play</small><div class="stat-bottom"><span class="green">●</span> Everyone’s here</div></div><div class="stat"><div class="stat-top">Courts available <span class="stat-icon">▥</span></div><strong>${m.courts}</strong><small>courts</small><div class="stat-bottom">${esc(m.venue.split(',')[0])}</div></div><div class="stat"><div class="stat-top">Session progress <span class="stat-icon">◷</span></div><strong>${done}<span style="font-size:16px;color:#9aa58f"> / ${m.matches.length}</span></strong><small>matches</small><div class="stat-bottom">${m.rounds} rounds scheduled</div></div><div class="stat"><div class="stat-top">Match opportunities <span class="stat-icon">⚖</span></div><strong>${Math.min(...c)}${Math.min(...c)!==Math.max(...c)?'–'+Math.max(...c):''}</strong><small>matches / player</small><div class="stat-bottom"><span class="green">↗</span> ${Math.max(...c)-Math.min(...c)<=1?'Balanced participation':'Review participation'}</div></div></div>`}
function matchTable(m,matches){return `<div class="table-wrap"><table><thead><tr><th>COURT</th><th>MATCHUP</th><th>STATUS</th><th></th></tr></thead><tbody>${matches.map(x=>`<tr><td><strong>0${x.court}</strong></td><td><div class="matchup"><strong>${teamText(m,x.teams[0])}</strong><span class="versus">vs</span><strong>${teamText(m,x.teams[1])}</strong></div></td><td><span class="pill">${x.status==='done'?x.score.join(' – '):x.status==='live'?'On court':'Upcoming'}</span></td><td>${x.status==='ready'?`<button class="inline-action" data-substitute="${x.id}">Substitute</button> · `:''}<button class="inline-action" data-result="${x.id}">${x.status==='done'?'View / edit':'Enter result'}</button></td></tr>`).join('')}</tbody></table></div>`}
function rest(m,r){const active=m.matches.filter(x=>x.round===r).flatMap(x=>x.teams.flat());const resting=m.players.filter((_,i)=>!active.includes(i));return `<div class="rest">☕ <strong>${resting.length?'Taking a breather':'Everyone on court'}</strong><span>${resting.length?resting.map(p=>esc(short(p.name))).join(' · '):'No resting players this round'}</span></div>`}
function courtCard(m,x){return `<article class="court-card"><div class="court-head"><div>Court 0${x.court}<small>${formatName(m)}</small></div><span class="badge ${x.status==='live'?'live':''}">${x.status==='live'?'Live match':x.status==='done'?'Completed':'Ready to play'}</span></div><div class="court-surface">${x.teams.map(t=>`<div class="team">${t.map(p=>`<div class="person"><span class="avatar">${initials(m.players[p].name)}</span><span>${esc(short(m.players[p].name))}</span></div>`).join('')}</div>`).join('')}<span class="court-middle">${x.status==='done'?x.score.join(' : '):'VS'}</span></div><div class="court-foot"><span class="timer" data-timer="${x.id}">${x.status==='done'?'✓ Result saved':x.started?'◷ '+elapsed(x):'◷ '+(m.timing?'Timer ready':'Timing off')}</span><button class="button ${x.status==='ready'?'primary':'lime'}" ${x.status==='ready'&&m.timing?`data-start="${x.id}"`:`data-result="${x.id}"`}>${x.status==='ready'?(m.timing?'▷ Start match':'Enter result'):x.status==='live'?'End & save result':'View result'} <span>↗</span></button></div>${x.status==='ready'?`<div class="match-actions"><button class="inline-action" data-substitute="${x.id}">Replace / substitute a player</button></div>`:''}</article>`}
function elapsed(x){const seconds=Math.max(0,Math.floor(((x.ended||Date.now())-x.started)/1000));return `${Math.floor(seconds/60).toString().padStart(2,'0')}:${(seconds%60).toString().padStart(2,'0')}`}
function fairness(m){const c=counts(m),min=Math.min(...c),max=Math.max(...c);const coverage=m.players.map((_,i)=>new Set(m.matches.filter(x=>x.teams.flat().includes(i)).flatMap(x=>x.teams.find(t=>t.includes(i)).filter(p=>p!==i))).size);return `<div class="card fair-card"><div class="card-title">A fair share of the court <span>✧</span></div><div class="fair-score"><strong>${min===max?'Even':max-min+' apart'}</strong><span>match allocation</span></div><p>${min===max?'Everyone has the same number of planned matches.':'The schedule keeps match opportunities close.'}</p><div class="bar"><i style="width:${100*min/Math.max(1,max)}%"></i></div><div class="metric"><span>Matches per player</span><b>${min===max?min:min+'–'+max}</b></div><div class="metric"><span>Distinct partners</span><b>${Math.min(...coverage)}–${Math.max(...coverage)}</b></div><div class="metric"><span>Partner preference</span><b>${m.mode==='fixed'?'Keep teams together':m.mode==='mixed'?'Fixed + rotating':m.mode==='balanced'?'Skill balance':'More variety'}</b></div><div class="fair-note">✓ ${m.mode==='fixed'?'Team continuity, with flexible substitutes.':'More people to play with. Less time waiting.'}<br>Prototype schedule · best-effort rotation${m.mode==='mixed'&&m.matches.length<m.courts*m.rounds?`<br>${m.courts*m.rounds-m.matches.length} court slots left open to improve participation balance.`:''}</div></div><div class="card details-card"><div class="card-title">The game plan</div><div class="detail-row"><span>♧</span><div><small>PARTNERS</small><strong>${modeName(m)}</strong></div></div><div class="detail-row"><span>⚑</span><div><small>MATCH FORMAT</small><strong>${formatName(m)}</strong></div></div><div class="detail-row"><span>◷</span><div><small>MATCH TIMING</small><strong>${m.timing?'Start & end controls enabled':'Optional timing disabled'}</strong></div></div><div class="detail-row"><span>▤</span><div><small>STATISTICS</small><strong>Optional winners & unforced errors</strong></div></div></div>`}
function render(){const m=meet();$('#crumb').textContent=m.name;$('#meet-title').textContent=m.name;$('#meet-meta').textContent=`${dateText(m)}  ·  ${m.time}  ·  ${m.duration/60}-hour session  ·  ${m.venue}`;$('#player-count').textContent=m.players.length;$('#meet-list').innerHTML=state.meets.map(x=>`<button class="meet-link ${x.id===m.id?'selected':''}" data-meet="${x.id}"><i class="dot ${x.id===m.id?'live':''}"></i>${esc(x.name)}</button>`).join('');document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('selected',b.dataset.view===currentView);b.classList.toggle('active',b.dataset.view===currentView);if(b.getAttribute('role')==='tab')b.setAttribute('aria-selected',b.dataset.view===currentView)});
  let html='';
  if(currentView==='overview')html=statsCards(m)+`<div class="layout"><div><div class="section-title"><h2>On the courts <span class="badge">Round ${round+1}</span></h2><div class="round-controls"><button data-round="-1" aria-label="Previous round" ${round===0?'disabled':''}>‹</button><span>${round+1} / ${m.rounds}</span><button data-round="1" aria-label="Next round" ${round===m.rounds-1?'disabled':''}>›</button></div></div><div class="courts">${m.matches.filter(x=>x.round===round).map(x=>courtCard(m,x)).join('')}</div>${rest(m,round)}<section class="next-section"><div class="section-title"><h2>${round<m.rounds-1?'Up next':'This round’s matches'}</h2><button class="inline-action" data-view="schedule">Full schedule ↗</button></div>${matchTable(m,m.matches.filter(x=>x.round===Math.min(round+1,m.rounds-1)))}</section></div><aside class="right-column">${fairness(m)}</aside></div>`;
  if(currentView==='schedule')html=`<div class="section-title"><h2>Your court rotation</h2><button class="button" id="regenerate">↻ Regenerate preview</button></div><div class="hint-banner">${m.rounds} rounds · ${m.matches.length} matches · ${modeName(m)}. This prototype uses a simple rotation; the production scheduler will handle full availability and fairness constraints.</div>${Array.from({length:m.rounds},(_,r)=>`<section class="schedule-round"><h3>Round ${String(r+1).padStart(2,'0')}</h3>${matchTable(m,m.matches.filter(x=>x.round===r))}${rest(m,r)}</section>`).join('')}`;
  if(currentView==='players'){const c=counts(m),done=counts(m,true);html=`<div class="section-title"><h2>The people make the game</h2><div class="section-actions"><button class="button" id="import">↙ Reclub preview</button>${m.mode==='mixed'?'<button class="button" id="mixed-pairs">Choose fixed pairs</button>':''}<button class="button primary" id="substitute">Add replacement player</button></div></div><p class="subtitle">${m.players.length} players · ${modeName(m)} · Planned appearances stay visible to everyone.</p><div class="table-wrap"><table><thead><tr><th>PLAYER</th>${m.mode==='fixed'?'<th>TEAM</th>':m.mode==='mixed'?'<th>PARTNER PREFERENCE</th>':m.mode==='balanced'?'<th>SKILL</th>':''}<th>PLANNED</th><th>COMPLETED</th><th>STATUS</th></tr></thead><tbody>${m.players.map((p,i)=>`<tr><td><div class="player-name"><span class="avatar">${initials(p.name)}</span><div><strong>${esc(p.name)}</strong><small>${p.replacement?'Replacement / substitute':'Sample club member'}</small></div></div></td>${m.mode==='fixed'?`<td>${p.team?'Team '+p.team:'Guest'}</td>`:m.mode==='mixed'?`<td>${m.fixedPairs?.find(t=>t.includes(i))?'Fixed with '+esc(short(m.players[m.fixedPairs.find(t=>t.includes(i)).find(j=>j!==i)].name)):'Rotating partners'}</td>`:m.mode==='balanced'?`<td><button class="inline-action" data-skill="${i}" aria-label="Edit skill for ${esc(p.name)}">${p.skill.toFixed(1)} · Edit</button></td>`:''}<td><strong>${c[i]}</strong><span class="count-track">${'<i></i>'.repeat(c[i])}</span></td><td>${done[i]}</td><td><span class="pill">${c[i]?'Checked in':'Not assigned'}</span></td></tr>`).join('')}</tbody></table></div><div class="hint-banner" style="margin-top:18px">Add a new replacement player here for remaining matches or the next match. To substitute an existing meet player for a specific match, open that match. Played matches retain their actual players and statistics.</div>`;}
  if(currentView==='history'){const done=m.matches.filter(x=>x.status==='done');html=`<div class="section-title"><h2>Every match, remembered</h2><span class="subtle">${done.length} completed matches</span></div>${done.length?done.map(x=>`<section class="schedule-round"><h3>Round ${x.round+1} · Court ${x.court} ${x.started?'· '+elapsed(x):''}</h3>${matchTable(m,[x])}<div class="table-wrap" style="margin-top:8px"><table><thead><tr><th>PLAYER</th><th>WINNERS</th><th>UNFORCED ERRORS</th><th>PADEL RATIO (W − UE)</th></tr></thead><tbody>${x.teams.flat().map(p=>{const s=x.stats[p]||{};return `<tr><td>${esc(m.players[p].name)}</td><td>${s.w??'—'}</td><td>${s.e??'—'}</td><td><strong>${s.w!=null&&s.e!=null?s.w-s.e:'—'}</strong></td></tr>`}).join('')}</tbody></table></div></section>`).join(''):'<div class="card empty"><strong>Your first match is waiting.</strong>Finish a match from the Overview to see scores and optional statistics here.<br><button class="button primary" style="margin-top:18px" data-view="overview">Go to the courts ↗</button></div>'}`;}
  if(currentView==='organizers')html=organizersView(m);
  $('#content').innerHTML=html;
}
function openModal(title,body,handler,label='Save'){ $('#modal-title').textContent=title;$('#modal-body').innerHTML=body;$('#modal-save').textContent=label;$('#form-error').textContent='';submitHandler=handler;$('#modal').showModal();}
$('#modal-form').addEventListener('submit',e=>{e.preventDefault();try{if(submitHandler(new FormData(e.target))!==false){$('#modal').close();persist();render()}}catch(error){$('#form-error').textContent=error.message}});
document.querySelectorAll('.close,.cancel').forEach(b=>b.onclick=()=>$('#modal').close());
function result(id){const m=meet(),x=m.matches.find(x=>x.id===id);openModal(x.status==='done'?'Match result':'Finish this match',`<div class="hint-banner">Court ${x.court} · Round ${x.round+1} · ${formatName(m)}<br>Enter games won. No small points or tiebreak details needed.</div>${x.status==='ready'?`<button type="button" class="button" data-substitute="${x.id}">Replace / substitute a player</button>`:''}${x.teams.map((t,i)=>`<label class="score-entry"><strong>${teamText(m,t)}</strong><input aria-label="Team ${i+1} games" name="score${i}" type="number" min="0" max="${target(m)}" required value="${x.score?.[i]??''}"></label>`).join('')}<div class="table-wrap stat-inputs"><table><caption>Optional player statistics</caption><thead><tr><th>PLAYER</th><th>WINNERS</th><th>ERRORS¹</th><th>RATIO²</th></tr></thead><tbody>${x.teams.flat().map(p=>`<tr data-statrow="${p}"><td>${esc(short(m.players[p].name))}</td><td><input aria-label="${esc(m.players[p].name)} winners" name="w${p}" type="number" min="0" value="${x.stats[p]?.w??''}"></td><td><input aria-label="${esc(m.players[p].name)} unforced errors" name="e${p}" type="number" min="0" value="${x.stats[p]?.e??''}"></td><td class="ratio">${x.stats[p]?.w!=null&&x.stats[p]?.e!=null?x.stats[p].w-x.stats[p].e:'—'}</td></tr>`).join('')}</tbody></table></div><p class="subtle" style="margin-top:12px;line-height:1.8">¹ Unforced errors. ² Padel ratio = winners − unforced errors.<br>Leave unknown statistics blank. Zero means none recorded.</p>`,data=>{const a=Number(data.get('score0')),b=Number(data.get('score1')),t=target(m);if(Math.max(a,b)!==t||a===b)throw Error(`A completed match needs one team at ${t} games and the other below ${t}.`);x.score=[a,b];x.stats={};x.teams.flat().forEach(p=>{x.stats[p]={w:data.get('w'+p)===''?null:Number(data.get('w'+p)),e:data.get('e'+p)===''?null:Number(data.get('e'+p))}});if(x.started&&!x.ended)x.ended=Date.now();x.status='done';toast('Match saved. A good game, in the books.');},'Save result');}
$('#modal-body').addEventListener('input',e=>{const row=e.target.closest('[data-statrow]');if(row){const inputs=row.querySelectorAll('input');row.querySelector('.ratio').textContent=[...inputs].every(i=>i.value!==''&&i.validity.valid)?Number(inputs[0].value)-Number(inputs[1].value):'—'}});
function settings(isNew=false){const m=meet(),hasPlayed=m.matches.some(x=>x.status!=='ready');openModal(isNew?'Plan your next meet':'Meet settings',`<div class="fields"><label class="field full">Meet name<input name="name" maxlength="50" required value="${isNew?'':esc(m.name)}" placeholder="Sunday morning rally"></label><label class="field full">Venue<input name="venue" required value="${esc(m.venue)}"></label><label class="field">Date<input name="date" type="date" required value="${m.date}"></label><label class="field">Start time<input name="time" type="time" required value="${m.time}"></label><label class="field">Players (sample roster)<input name="players" type="number" min="4" max="24" required value="${isNew?8:m.players.length}"></label><label class="field">Courts<input name="courts" type="number" min="1" max="6" required value="${m.courts}"></label><label class="field">Rounds<input name="rounds" type="number" min="1" max="12" required value="${m.rounds}"></label><label class="field">Duration (minutes)<input name="duration" type="number" min="30" max="480" step="15" required value="${m.duration}"></label><label class="field">Partner mode<select name="mode">${[['rotating','Rotating · variety'],['balanced','Rotating · skill balance'],['fixed','Fixed partners'],['mixed','Mixed · fixed & rotating']].map(([v,t])=>`<option value="${v}" ${v===m.mode?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">Match format<select name="format">${[['4','Race to 4 games'],['6','Race to 6 games'],['5','Best of 5 games']].map(([v,t])=>`<option value="${v}" ${v===m.format?'selected':''}>${t}</option>`).join('')}</select></label></div><label class="checkbox"><input type="checkbox" name="timing" ${m.timing?'checked':''}> Enable optional start / end timing</label><div class="hint-banner">Sample players are included automatically. ${!isNew&&hasPlayed?'This meet has started; use Create meet to explore a different setup.':'Saving generates a new sample schedule. Fixed partners are paired in roster order. Mixed mode starts with the first two players fixed; choose your pairs in Players.'}</div>`,data=>{if(!isNew&&hasPlayed)throw Error('This meet has played or active matches. Create a new meet to preserve its history.');const n=Number(data.get('players')),c=Number(data.get('courts'));if(data.get('mode')==='fixed'&&n%2)throw Error('Fixed partners need an even number of players.');if(c>Math.floor(n/4))throw Error('Each court needs four players. Reduce courts or add players.');const name=data.get('name').trim();if(!name)throw Error('Enter a meet name.');const next=makeMeet(isNew?'meet-'+Date.now():m.id,name,n,c,Number(data.get('rounds')),data.get('mode'),data.get('format'));Object.assign(next,{venue:data.get('venue').trim(),date:data.get('date'),time:data.get('time'),duration:Number(data.get('duration')),timing:data.has('timing')});if(!isNew){next.organizers=[...(m.organizers||[])];if(next.mode==='mixed'&&m.mode==='mixed'){const pairs=(m.fixedPairs||[]).filter(t=>t.every(i=>i<n));if(pairs.length&&n-pairs.flat().length>=2)next.fixedPairs=pairs;}next.players.forEach((p,i)=>{if(m.players[i])p.skill=m.players[i].skill;});generate(next);}if(isNew)state.meets.push(next);else state.meets[state.meets.indexOf(m)]=next;state.selected=next.id;round=0;currentView='overview';toast(isNew?'Your new meet is ready.':'Meet updated and sample schedule generated.');},isNew?'Create meet':'Save & generate');}
function registeredSubstitutes(m,match){return m.players.map((p,i)=>({p,i})).filter(({i})=>!match.teams.flat().includes(i));}
function substitute(matchId=null){
 const m=meet(),selected=matchId?m.matches.find(x=>x.id===matchId):null;
 if(matchId&&(!selected||selected.status!=='ready'))return toast('Only unstarted matches can be substituted.');
 const eligible=m.players.map((p,i)=>({p,i})).filter(({i})=>selected?selected.teams.flat().includes(i):m.matches.some(x=>x.status==='ready'&&x.teams.flat().includes(i)));
 if(!eligible.length)return toast('No unstarted matches remain.');
 const options=selected?registeredSubstitutes(m,selected):[];
 openModal(selected?'Substitute for this match':'Add a replacement player',`<div class="hint-banner">${selected?`Round ${selected.round+1} · Court ${selected.court}. Choose a player already registered in this meet. This change affects this match only.`:'Register a new player and replace an existing player for the next unstarted match or the remaining meet.'} Earlier results and statistics stay unchanged.</div><div class="fields"><label class="field full">Player being replaced<select name="out">${eligible.map(({p,i})=>`<option value="${i}">${esc(p.name)}</option>`).join('')}</select></label>${selected?`<label class="field full">Registered substitute<select name="incoming" required><option value="">Choose a player</option>${options.map(({p,i})=>`<option value="${i}">${esc(p.name)}</option>`).join('')}</select></label><p class="subtle field full">${options.length?'All registered players outside this match are listed, including players assigned elsewhere or currently playing.':'Every registered player is already in this match. Add a new replacement from the Players list if needed.'}</p>`:`<label class="field full">New player’s name<input name="name" required maxlength="60" placeholder="e.g. Adi Nugroho"></label>${m.mode==='balanced'?'<label class="field full">Skill level (1–5)<input name="skill" type="number" min="1" max="5" step="0.5" required value="3"></label>':''}<label class="field full">Replacement scope<select name="scope"><option value="one">Next unstarted match only</option><option value="meet">Remaining meet</option></select></label>`}</div>`,data=>{
 const out=Number(data.get('out'));if(!eligible.some(v=>v.i===out))throw Error('Choose an eligible outgoing player.');
 if(selected){if(selected.status!=='ready'||!selected.teams.flat().includes(out))throw Error('This match changed. Reopen it to choose a substitute.');const raw=data.get('incoming');if(raw===null||raw==='')throw Error('Choose a registered substitute.');const incoming=Number(raw);if(!registeredSubstitutes(m,selected).some(v=>v.i===incoming))throw Error('The substitute must be registered in this meet and not already in this match.');selected.teams=selected.teams.map(t=>t.map(p=>p===out?incoming:p));selected.changes=[...(selected.changes||[]),{out,incoming,scope:'one',source:'match'}];toast(m.players[incoming].name+' substituted for this match only.');return;}
 const name=String(data.get('name')||'').trim();if(!name)throw Error('Enter a new player name.');if(m.players.some(p=>p.name.toLowerCase()===name.toLowerCase()))throw Error('This player is already registered. Open a match to select them as a substitute.');
 let affected=m.matches.filter(x=>x.status==='ready'&&x.teams.flat().includes(out));if(!affected.length)throw Error('No unstarted matches remain for this player.');const scope=data.get('scope');if(!['one','meet'].includes(scope))throw Error('Choose a replacement scope.');if(scope==='one')affected=affected.slice(0,1);
 const skill=m.mode==='balanced'?Number(data.get('skill')):3;if(!Number.isFinite(skill)||skill<1||skill>5||skill*2%1)throw Error('Enter a skill from 1 to 5 in steps of 0.5.');
 const incoming=m.players.length;m.players.push({name,skill,team:m.players[out].team,replacement:true});if(m.mode==='mixed'&&scope==='meet')m.fixedPairs=(m.fixedPairs||[]).map(t=>t.map(p=>p===out?incoming:p));affected.forEach(x=>{x.teams=x.teams.map(t=>t.map(p=>p===out?incoming:p));x.changes=[...(x.changes||[]),{out,incoming,scope,source:'players'}]});toast(name+' registered and assigned to '+affected.length+' match'+(affected.length===1?'':'es')+'.');
 },selected?'Save substitution':'Register & replace');
}
function importPreview(){openModal('Reclub roster preview',`<div class="hint-banner">Demo only: no webpage is fetched. The full application will scrape the Reclub URL and let you review players before importing.</div><label class="field">Reclub meet URL<input name="url" type="url" placeholder="Paste a Reclub meet URL (optional in demo)"></label><div style="margin-top:20px"><strong>Sample imported roster</strong>${names.slice(0,4).map(n=>`<div class="detail-row"><span class="avatar">${initials(n)}</span><div><strong>${n}</strong><small>Sample attendee · already in demo roster</small></div><span class="pill">Matched</span></div>`).join('')}</div>`,()=>{toast('Sample preview reviewed. No live import was performed.');},'Done');}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const m=meet();if(b.dataset.view){currentView=b.dataset.view;render()}if(b.dataset.meet){state.selected=b.dataset.meet;round=0;currentView='overview';persist();render()}if(b.dataset.round){round=Math.max(0,Math.min(m.rounds-1,round+Number(b.dataset.round)));render()}if(b.dataset.start){const x=m.matches.find(x=>x.id===b.dataset.start);const conflict=m.matches.some(y=>y.status==='live'&&(y.court===x.court||y.teams.flat().some(p=>x.teams.flat().includes(p))));if(conflict)return toast('Finish the active match on this court or with these players first.');x.status='live';x.started=Date.now();persist();render();toast(`Court ${x.court} is live. Enjoy the match!`)}if(b.dataset.result)result(b.dataset.result);if(b.id==='new-meet'||b.id==='add-meet')settings(true);if(b.id==='settings')settings();if(b.id==='mixed-pairs')configureMixedPairs();if(b.id==='substitute')substitute();if(b.dataset.substitute)substitute(b.dataset.substitute);if(b.dataset.skill!==undefined)editSkill(Number(b.dataset.skill));if(b.id==='club-organizers')manageOrganizers('club');if(b.id==='meet-organizers')manageOrganizers('meet');if(b.id==='import')importPreview();if(b.id==='regenerate'){if(m.matches.some(x=>x.status!=='ready'||x.changes))return toast('Keep this schedule to preserve started matches and substitutions. Create a new meet to try another setup.');generate(m);persist();render();toast('Preview regenerated with the same reproducible rotation.')}if(b.id==='reset')openModal('Reset the sample workspace?','<p>This removes this prototype’s locally saved meets, results, and statistics and restores the two sample meets.</p>',()=>{state=fresh();round=0;currentView='overview';toast('Sample workspace restored.');},'Reset demo');});
setInterval(()=>{const m=meet();document.querySelectorAll('[data-timer]').forEach(el=>{const x=m.matches.find(x=>x.id===el.dataset.timer);if(x?.status==='live')el.textContent='◷ '+elapsed(x)})},1000);

function editSkill(index){const m=meet(),p=m.players[index];if(m.mode!=='balanced'||!p)return;openModal('Edit player skill',`<p class="subtitle">${esc(p.name)}</p><label class="field">Skill level (prototype scale: 1–5)<input name="skill" type="number" min="1" max="5" step="0.5" required value="${p.skill}"></label><div class="hint-banner" style="margin-top:16px">Updates the meet’s player rating. Existing match assignments stay unchanged. Regenerate an unstarted schedule to use the updated ratings.</div>`,data=>{const value=Number(data.get('skill'));if(!Number.isFinite(value)||value<1||value>5||value*2%1)throw Error('Enter a skill from 1 to 5 in steps of 0.5.');p.skill=value;toast('Skill saved. Existing assignments are unchanged.');},'Save skill');}
function organizersView(m){const list=ids=>ids.map(id=>state.users.find(u=>u.id===id)).filter(Boolean);const cards=(users,role)=>users.length?users.map(u=>`<div class="organizer-row"><span class="avatar">${esc(initials(u.name))}</span><div><strong>${esc(u.name)}</strong><small>${role}</small></div></div>`).join(''):'<p class="subtitle">No meet organizers assigned yet. Club organizers can still manage this meet.</p>';return `<div class="section-title"><h2>A shared effort</h2></div><p class="subtitle">Club organizers oversee every meet. Meet organizers help run only their assigned meet.</p><div class="organizer-grid"><section class="card"><div class="section-title"><h2>Club organizers</h2><button class="button" id="club-organizers">Manage</button></div><p>${esc(state.club.name)} · All club meets</p>${cards(list(state.club.organizers),'Club organizer')}</section><section class="card"><div class="section-title"><h2>Meet organizers</h2><button class="button primary" id="meet-organizers">Assign</button></div><p>${esc(m.name)} only</p>${cards(list(m.organizers||[]),'Meet organizer')}</section></div><div class="hint-banner" style="margin-top:20px">A player can also be a meet organizer. Meet assignments do not grant club-wide access. This prototype demonstrates role assignments; sign-in and permission enforcement will be implemented in the application.</div>`;}
function manageOrganizers(scope){const m=meet(),club=scope==='club',assigned=club?state.club.organizers:(m.organizers||[]);openModal(club?'Manage club organizers':'Assign meet organizers',`<div class="hint-banner">${club?'Choose one or more club organizers. They can manage all club meets and assign meet organizers.':'Choose users to manage this meet’s roster, schedule, substitutions, results and statistics. Players can hold this role too.'}</div><div class="organizer-options">${state.users.map(u=>`<label class="checkbox"><input type="checkbox" name="organizer" value="${u.id}" ${assigned.includes(u.id)?'checked':''}><span>${esc(u.name)}${m.players.some(p=>p.name===u.name)?' · player in this meet':''}</span></label>`).join('')}</div>`,data=>{const ids=[...new Set(data.getAll('organizer'))];if(ids.some(id=>!state.users.some(u=>u.id===id)))throw Error('Choose an existing user.');if(club&&!ids.length)throw Error('Keep at least one club organizer.');if(club)state.club.organizers=ids;else m.organizers=ids;toast(club?'Club organizers updated.':'Meet organizers assigned to this meet only.');},'Save organizers');}


function generateMixed(m){
 const fixed=m.fixedPairs||[[0,1]],locked=new Set(fixed.flat()),pool=m.players.map((_,i)=>i).filter(i=>!locked.has(i));
 if(fixed.length<1||pool.length<2||locked.size!==fixed.length*2||fixed.some(t=>t.length!==2||t.some(i=>!Number.isInteger(i)||!m.players[i])))throw Error('Mixed mode needs distinct fixed pairs and at least two rotating players.');
 let seed=91;const random=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};const shuffle=a=>{a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};const pair=(a,b)=>[a,b].sort((x,y)=>x-y).join('-');
 let bestSchedule,bestFinal=Infinity;
 for(let attempt=0;attempt<24;attempt++){
  const counts=m.players.map(()=>0),partners={},opponents={},lastRest=m.players.map(()=>0);let matches=[],variety=0;
  for(let r=0;r<m.rounds;r++){
   let choice,score=Infinity;
   for(let trial=0;trial<70;trial++){
    const singles=shuffle(pool);singles.sort((a,b)=>counts[a]-counts[b]);const teams=fixed.map(t=>[...t]);for(let i=0;i+1<singles.length;i+=2)teams.push(singles.slice(i,i+2));
    const ranked=shuffle(teams).map(t=>({t,value:counts[t[0]]+counts[t[1]]+random()*1.6})).sort((a,b)=>a.value-b.value);
    const capacity=Math.min(m.courts,Math.floor(teams.length/2));const used=attempt>=12&&capacity>1&&trial%4===0?capacity-1:capacity;const selected=shuffle(ranked.slice(0,used*2).map(v=>v.t));const ids=new Set(selected.flat()),next=counts.map((v,i)=>v+(ids.has(i)?1:0));
    let repeats=0;for(let i=0;i<selected.length;i+=2){for(const t of [selected[i],selected[i+1]])if(!locked.has(t[0]))repeats+=(partners[pair(...t)]||0)*5;for(const a of selected[i])for(const b of selected[i+1])repeats+=opponents[pair(a,b)]||0;}
    const restPenalty=lastRest.reduce((s,v,i)=>s+(ids.has(i)?0:(v+1)**2),0);
    const cost=(Math.max(...next)-Math.min(...next))*10000+next.reduce((s,v)=>s+(v-next.reduce((a,b)=>a+b,0)/next.length)**2,0)*100-selected.length*20+restPenalty*10+repeats;
    if(cost<score){score=cost;choice=selected;}
   }
   const active=new Set(choice.flat());counts.forEach((_,i)=>{if(active.has(i))counts[i]++;lastRest[i]=active.has(i)?0:lastRest[i]+1});
   for(let c=0;c<choice.length;c+=2){const teams=[choice[c],choice[c+1]];for(const t of teams){const k=pair(...t);if(!locked.has(t[0]))variety+=partners[k]||0;partners[k]=(partners[k]||0)+1;}for(const a of teams[0])for(const b of teams[1]){const k=pair(a,b);opponents[k]=(opponents[k]||0)+1;}matches.push({id:m.id+'-'+r+'-'+c/2,round:r,court:c/2+1,teams,status:'ready',stats:{}});}
  }
  const cost=(Math.max(...counts)-Math.min(...counts))*100000+-matches.length*100+variety;
  if(cost<bestFinal){bestFinal=cost;bestSchedule=matches;}
 }
 m.matches=bestSchedule;
}
function configureMixedPairs(){const m=meet();if(m.mode!=='mixed')return;if(m.matches.some(x=>x.status!=='ready'||x.changes))return toast('Fixed pairs can be edited before play or substitutions begin.');const slots=Math.floor((m.players.length-2)/2);const options=value=>'<option value="">Choose player</option>'+m.players.map((p,i)=>'<option value="'+i+'" '+(i===value?'selected':'')+'>'+esc(p.name)+'</option>').join('');openModal('Choose fixed partners','<div class="hint-banner">These pairs stay together. Everyone else rotates partners. Leave unused rows blank and keep at least two players in the rotating pool. Saving regenerates the unstarted schedule.</div>'+Array.from({length:slots},(_,i)=>'<div class="fields" style="margin-bottom:14px"><label class="field">Pair '+(i+1)+' · player 1<select name="pair'+i+'a">'+options(m.fixedPairs?.[i]?.[0])+'</select></label><label class="field">Player 2<select name="pair'+i+'b">'+options(m.fixedPairs?.[i]?.[1])+'</select></label></div>').join(''),data=>{const pairs=[];for(let i=0;i<slots;i++){const a=data.get('pair'+i+'a'),b=data.get('pair'+i+'b');if(a===''&&b==='')continue;if(a===null||b===null||a===''||b==='')throw Error('Choose both players for each fixed pair.');pairs.push([Number(a),Number(b)]);}const ids=pairs.flat();if(!pairs.length||ids.some(i=>!Number.isInteger(i)||!m.players[i])||new Set(ids).size!==ids.length||m.players.length-ids.length<2)throw Error('Choose distinct fixed pairs and leave at least two rotating players.');m.fixedPairs=pairs;generate(m);toast('Fixed pairs saved and fair rotation regenerated.');},'Save pairs & generate');}

render();
